window.LD=window.LD||{};window.LD["hero/h4"]={"id":"h4","name":"Allie","owner":"Allie","npc":false,"pronoun":"she/they","cls":"cryomancer","title":"Cryomancer","level":11,"look":{"skin":"#f6d5b8","hair":"#7a4424","style":6,"face":0,"fav":"#7a4cc8","fav_name":"purple","scars":[]},"pet":{"kind":"dog","name":"Pepper"},"mount":null,"alive":true,"keepsake":null,"maps":[{"dungeon":"cragtooth_warren","pct":43,"worked":21}],"party":"p3","party_name":"The Pack of Carrbridge","loc":"cragtooth_warren","loc_name":"Cragtooth Warren","travel":null,"rep":{"carrbridge":18,"thornwall":4,"hollowood":3,"ironhaven":3},"curse":null,"fstanding":{"thorns":-4.0,"scale":2.0},"faction":null,"frank":0,"doing":"delving into Cragtooth Warren","why":"after the boss: about 40 silver a day each, risk slight; itching to get underground again","delve":{"now":null,"last":{"dest":"cragtooth_warren","day":30,"days":4,"why":"after the boss: about 40 silver a day each, risk slight; itching to get underground again","packed":{"torches":32,"rations":18},"turn":null,"rooms":6}},"route":"Day 30: spent the day in Cragtooth Warren.","today":["Fought 1 fight: won 1.","+234 XP, reached level 11.","Coin: +7 silver.","Came away with 2 goblin ears.","Ate 2 rations.","Used up 2 torches.","New gear: Egg That Is Still Warm.","Stress: −27 a dream come true, +10 nights in the dark, +4 camping out, −3 a good night underground, −3 a game by the fire, −2 good company."],"fights_today":["f81"],"tables_today":[{"table":"Won at checkers against Katie","game":"n39","route":"night"}],"daybook":{"day":30,"label":"Day 30","title":"Season 1, day 30, hour by hour","blocks":[{"act":"delve","label":"Walking","from":6.0,"to":7.0,"line":"Back through 2 cleared rooms on the first floor.","fights":["f81"]},{"act":"delve","label":"Picked clean","from":7.0,"to":8.5,"line":"Chalk arrows at the drain cut point the way someone else went. The crew follows them round, mapping as they go.","room":{"floor":1,"room":13,"fight":null,"dungeon":"cragtooth_warren"}},{"act":"delve","label":"Walking","from":8.5,"to":9.0,"line":"Back through 1 cleared room on the first floor."},{"act":"delve","label":"Picked clean","from":9.0,"to":10.5,"line":"Boot prints in the dust at the hoard-sorting cave, a snapped arrow, and nothing left worth the walk. Still, it goes on the map.","room":{"floor":1,"room":19,"fight":null,"dungeon":"cragtooth_warren"}},{"act":"delve","label":"Walking","from":10.5,"to":11.5,"line":"Back through 2 cleared rooms on the first floor."},{"act":"delve","label":"Down","from":11.5,"to":12.0,"line":"Down to the bottom floor."},{"act":"delve","label":"Walking","from":12.0,"to":15.0,"line":"Back through 6 cleared rooms on the bottom floor."},{"act":"delve","label":"Fight","from":15.0,"to":18.0,"line":"Kobolds trot in single file with a chest on each head. At the sight of strangers every chest is put down. Allie counts heads from the shadows: 3 goblin archers. Now they know what they're walking into. A note in the corner reads 'nothing here, sorry', and it is right.","room":{"floor":2,"room":13,"fight":"f81","dungeon":"cragtooth_warren"}}],"evening":{"kind":"dungeon","line":"Camped in Cragtooth Warren","more":[{"table":"Won at checkers against Katie","game":"n39","route":"night"}]},"wday":30},"grew":[],"progress":null,"goal":{"text":"to sit beneath the Mother Oak in Hollowood","kind":"pilgrimage","done":17,"progress":"hasn't set out for Hollowood yet","missed":false,"crew":"The Pack of Carrbridge","party":"p3"},"vows":[],"renown":170,"epithet":null,"gold":37,"copper":2,"hp":148,"maxhp":148,"injuries":[],"legend":false,"weapon":"wand","weapon_tier":2,"armor":"cloth","armor_tier":2,"kit":{"weapon":{"family":"wand","tier":2,"two":false,"glow":null},"offhand":{"art":"tome","tier":1,"glow":null},"armor":{"material":"cloth","tier":2,"outfit":"vestments","glow":null},"head":{"art":"circlet","tier":1,"glow":null},"back":null,"neck":null,"rings":[],"pocket":{"art":"egg","tint":"#e8dcc8","glow":null},"belt":null,"boots":null,"gloves":null,"mark":"ice_crown"},"vox":{"bold":0.25,"style":"earnest"},"jail":0,"away":false,"died_day":null,"died_season":null,"died_sday":null,"joined":1,"lodging":"common","power":180,"home":null,"sleep":{"setting":"camp","place":"Camped outside Cragtooth Warren","gate":"cragtooth_warren"},"dream":"to set foot in six of the realm's towns","trophies":[],"cabinet":[{"id":"honour:banned_song:1","kind":"honour","honour":"banned_song","name":"Had a Song About Them Banned in Hollowood","season":1,"tone":"tease"}],"stats":{"might":8,"agility":9,"mind":20,"grit":14,"heart":8},"eff":{"might":8,"agility":9,"mind":20,"grit":14,"heart":8},"traits":{"boldness":0.246,"risk":-0.72,"greed":-0.68,"sociability":0.36,"honor":0.93,"curiosity":-0.31,"temper":-0.22,"loyalty":0.08},"aff":{"trade":0.7,"stealth":1.0,"command":0.1,"lore":0.1,"holy":3.2,"crit":0.6,"heal":1.9,"travel":2.2,"guard":2.9,"ice":5.0,"music":0.6,"fire":1.0,"storm":2.8,"beast":2.8,"arcane":2.0,"craft":0.3,"nature":0.3,"fate":2.2,"hunt":0.1},"lean_aff":{"trade":0.2,"stealth":1.0,"command":0.1,"lore":0.1,"holy":2.7,"crit":0.1,"heal":1.2,"travel":0.6,"guard":2.5,"ice":3.8,"music":0.3,"fire":1.0,"storm":2.4,"beast":2.0,"arcane":2.0,"craft":0.5,"nature":0.5,"fate":3.4,"hunt":0.0},"growth":{"might":1.0,"agility":1.3,"mind":2.8,"grit":1.75,"heart":1.3},"skills":[{"id":"frost_shard","rank":2,"name":"Frost Shard","desc":"A spike of winter.","tags":["ice"],"type":"attack","uses":11,"school":"frost","side":false,"own":false,"keystone":null},{"id":"mend_wounds","rank":1,"name":"Mend Wounds","desc":"Knits flesh with a word.","tags":["heal","holy"],"type":"heal","uses":2,"school":"healing","side":false,"own":false,"keystone":null},{"id":"blink","rank":1,"name":"Blink","desc":"Is suddenly two feet to the left.","tags":["stealth"],"type":"passive","uses":0,"school":"arcane","side":false,"own":false,"keystone":null},{"id":"lanternlight","rank":1,"name":"Lanternlight","desc":"A little floating flame, always where it's needed.","tags":["fire","arcane"],"type":"world","uses":0,"school":"flame","side":false,"own":false,"keystone":null},{"id":"vigil","rank":1,"name":"Vigil","desc":"Keeps watch and prays through the small hours.","tags":["holy","guard"],"type":"world","uses":0,"school":"holy","side":false,"own":false,"keystone":null},{"id":"arc_lightning","rank":1,"name":"Arc Lightning","desc":"Jumps between targets. Hair stands up.","tags":["storm"],"type":"multi","uses":5,"school":"storm","side":false,"own":false,"keystone":null},{"id":"mana_surge","rank":1,"name":"Mana Surge","desc":"Spells hit harder.","tags":["arcane"],"type":"passive","uses":0,"school":"arcane","side":false,"own":false,"keystone":null},{"id":"ice_wall","rank":1,"name":"Ice Wall","desc":"Slams a wall of ice down in front of the party.","tags":["ice","guard"],"type":"buff_all","uses":5,"school":"frost","side":false,"own":false,"keystone":null},{"id":"glacial_wall","rank":1,"name":"Glacial Wall","desc":"A wall of ice between friends and foes.","tags":["ice","guard"],"type":"buff_all","uses":1,"school":"frost","side":false,"own":true,"keystone":null},{"id":"endless_winter","rank":1,"name":"Endless Winter","desc":"Wherever they stand, it's January.","tags":[],"type":"aoe","uses":1,"school":null,"side":false,"own":false,"keystone":10,"does":"In a fight they can unleash a blast of cold that hits every enemy and leaves them slow and easier to hit for several rounds."},{"id":"lightning_bolt","rank":1,"name":"Lightning Bolt","desc":"Straight through the armour, smelling of rain.","tags":["storm"],"type":"attack","uses":0,"school":"storm","side":false,"own":false,"keystone":null}],"kit_items":[{"slot":"weapon","name":"Hedge Wand","art":"wand","tier":2,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"","story":"Bought from Widow Saffery in Carrbridge","day":10,"history":[],"plus":"hits harder on every blow (+8 power)"},{"slot":"armor","name":"Traveler's Garb","art":"cloth","tier":2,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"","story":"Bought from Widow Saffery in Carrbridge","day":14,"history":[],"plus":"harder to hurt (+3 armour)"},{"slot":"offhand","name":"Spellbook","art":"tome","tier":1,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"Hits a little harder (+2% power)","story":"Bought in Carrbridge","day":24,"history":[],"plus":null},{"slot":"head","name":"Silver Circlet","art":"circlet","tier":1,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"A little braver (+2 nerve)","story":"A gift from the guild on her new calling","day":22,"history":[],"plus":null},{"slot":"pocket","name":"Egg That Is Still Warm","art":"egg","tier":null,"gem":null,"tint":"#e8dcc8","glow":null,"magic":false,"enchant":null,"desc":"Found in a nest nobody was guarding. It has not hatched. It stays warm. Nobody has asked what's inside.","fx":"","story":"on the kobold in Cragtooth Warren","day":28,"history":[{"day":28,"text":"Found on the kobold in Cragtooth Warren, by Katie"},{"day":30,"text":"Lost to Allie on a bet at checkers, at camp in Cragtooth Warren"}],"plus":null}],"row":"back","curios":[],"sets":[{"name":"Slate and Chalk Checkers","kind":"checkers","tier":1,"art":"button","desc":"Veldrock slate and chalk pieces, heavy to push and impossible to knock over by accident.","look":"Flat grey slate discs and white chalk-dusted discs on a board scratched into a mine-cart lid","condition":"like new","missing":0,"games":2,"story":"Bought in Carrbridge for 6 silver 4 copper","history":[{"day":14,"text":"Bought in Carrbridge for 6 silver 4 copper, by Allie"}]},{"name":"Good Dog Tarot","kind":"tarot","tier":1,"art":"cards","desc":"A Carrbridge fair deck in which every figure is a dog, from the Fool's terrier to the spaniel Queen of Cups.","look":"Storybook gouache in a brick-red frame, every figure a dog, a bone for a name-plate","condition":"like new","missing":0,"games":1,"story":"A gift","history":[{"day":20,"text":"A gift to Allie, from no one quite knows where"}]},{"name":"Driftwood Chess","kind":"chess","tier":1,"art":"figurine","desc":"Saltmarrow chess carved from the tide line, every bishop a bit crooked and all of them smelling of the sea.","look":"Salt-bleached pale driftwood and tarred dark driftwood, pieces roughly whittled, a board of oiled planks","condition":"like new","missing":0,"games":2,"story":"Bought in Carrbridge for 11 silver","history":[{"day":24,"text":"Bought in Carrbridge for 11 silver, by Allie"}]}],"h2h":{"rows":[{"vs":"h16","kind":"checkers","won":2,"lost":0,"games":2,"last":30,"run":["h4",2]},{"vs":"h16","kind":"chess","won":2,"lost":0,"games":2,"last":29,"run":["h4",2]},{"vs":"h16","kind":"dice","won":0,"lost":1,"games":1,"last":13,"run":["h16",1]}],"prefs":{"cards":0.0683,"dice":0.0001,"checkers":0.3217,"chess":0.4222,"tarot":0.1877},"nicks":{}},"pastimes":{"keen":{"sing":0.115,"play":0.043,"cook":0.254,"fish":0.448,"game":0.842},"skill":{"sing":0.559,"play":0.0,"cook":0.025,"fish":0.0,"game":0.464}},"purse":[[1,300,null],[2,300,{}],[3,170,{"rations":-50,"tavern":-10,"beds":-70}],[4,190,{"work":90,"tavern":-10,"beds":-60}],[5,210,{"work":90,"tavern":-10,"beds":-60}],[6,210,{}],[7,210,null],[8,390,null],[9,830,null],[10,370,null],[11,280,{"gear":-90}],[12,380,{"loot":100}],[13,880,{"loot":500}],[14,166,{"sales":30,"bounties":80,"rations":-50,"gear":-620,"hobbies":-64,"tavern":-10,"food":-20,"beds":-60}],[15,126,{"tavern":-10,"beds":-30}],[16,126,{}],[17,66,{"rations":-30,"tavern":-10,"beds":-20}],[18,6,{"rations":-60}],[19,26,{"sales":60,"bounties":20,"rations":-20,"tavern":-10,"beds":-30}],[20,26,{}],[21,26,{}],[22,286,{"old kit sold":30,"loot":230}],[23,376,{"loot":90}],[24,234,{"road event":-10,"sales":120,"bounties":60,"gear":-130,"hobbies":-112,"beds":-70}],[25,12,{"rations":-120,"goods":-60,"road event":-2,"tavern":-10,"beds":-30}],[26,92,{"loot":80}],[27,92,{}],[28,162,{"loot":70}],[29,302,{"loot":90,"treasure":50}],[30,372,{"loot":70}]],"music":{"band":0.559,"label":"decent","inst":[],"songs":[{"src":"folk","id":"parsley_thyme","title":"Parsley, Sage and Thyme","tone":"sad","meter":"3/4","bpm":92,"diff":2,"n":1}],"wrote":[],"played":2.0,"n":{"choir":1,"led":1},"anthem":null,"moments":[],"lately":[{"id":"n35","day":28,"title":"Parsley, Sage and Thyme","src":"folk","role":"led","outcome":"rough","where":"camp","place":"camp in Cragtooth Warren","lead":"h4"}]},"omens":{"active":[],"log":[],"reads":{"read":1,"checked":3,"hits":2}},"table":{"favourite":"fried","favourite_name":"fried things","keeps_parts":true,"cook":0,"cooks":false,"dishes":[{"id":"ration_hash","name":"Ration-Bag Hash","n":1,"love":true},{"id":"spice_pilaf","name":"Spice-Barge Pilaf","n":1,"love":false},{"id":"twist_bread","name":"Twist-Bread on a Stick","n":1,"love":false}],"recent":[{"day":27,"meal":"m36","dish":"twist_bread","text":"Katie cooks some Twist-Bread on a Stick in Cragtooth Warren. It has a scorch mark exactly where the cook looked away."},{"day":26,"meal":"m34","dish":"ration_hash","text":"Ration-Bag Hash in Cragtooth Warren, by Katie. Allie goes very quiet, which is how Allie says thank you for her favourite."},{"day":14,"meal":"m1","dish":"spice_pilaf","text":"Allie has some Spice-Barge Pilaf at The Honest Toll and sends compliments to Jolly Mott. It has a raisin in every third mouthful, by tradition. (2 silver)"}],"knack":0.5,"cooked":[]},"angler":null,"next_class":{"level":18,"id":"winters_warden","name":"Winter's Warden","alt":"Frostweaver","why":["standing in front of friends","frost"]},"travellers":[["loom","Doctor Fabian Loom",1],["marigold","Marigold",1]],"goals_log":[{"season":1,"kind":"pilgrimage","text":"to sit beneath the Mother Oak in Hollowood","done":true,"crew":"The Pack of Carrbridge"}],"vow_log":[],"letters":[{"day":7,"season":1,"text":"Hello from the King's Road, and thank you for your last note. This week I spent an afternoon in Saltmarrow learning from Brother Toad, and I am sore but truly better for it. Katie and I formed The Pack of Carrbridge over at The Honest Toll, and she has already taught me a card trick. I reached level 3 and learned Blink, though I still don't like the dark. Pepper stays close. I hope you are all being sensible. With kindest regards, — Allie","voice":"earnest"},{"day":14,"season":1,"text":"Hello again, dear ones. There was a fire at the bakery in Carrbridge, so I joined the bucket line and came out smelling of smoke and burnt bread. Katie and I have become friends, the slow, honest kind that starts with sharing a fire, even though she beat me at dice by a single pip and I checked the pip. I want a rematch. I reached level 8 and learned Ice Wall, and I also lost the bet, so the night watch is mine now. Be gentle with each other. — Allie","voice":"earnest"},{"day":21,"season":1,"text":"Dearest everyone, a gentle week. On the King's Road at night I carried a small flame in my cupped hand, and the wind left it alone, which felt like a kindness. Katie went off after something that sang in the dark and came back quiet, with a trinket. Pepper growled at the dark until I got up to look. Nothing there, though Pepper disagrees. The wolves on the Thornwall road were dealt with, and my Frost Shard did the damage, twice. I still don't love the dark, but I managed. Thinking of you all. Warmly, — Allie","voice":"earnest"},{"day":28,"season":1,"text":"Dearest ones, I reached level ten and learned Lightning Bolt, though what I'll remember is the chief's hall in Cragtooth Warren. My hands shook the whole fight, because of the dark, but I stayed, and my Ice Wall helped tilt it. Frost raced out from my feet too, Endless Winter, and every foe slowed to a shiver. Afterward I built Katie an ice chair. It was surprisingly comfortable, briefly. We've had our first chess game, and I won by a whisker, and she is keeping score. Pepper slept soundly. Please be well. Warmly, — Allie","voice":"earnest"}],"voice":"earnest","threads":[],"renown_parts":[["levels",60],["deeds and stories",45],["silver earned",25],["kills",23],["a steady hand",12],["dungeon floors",3],["delves",2]],"class_history":[[0,"mage"],[22,"cryomancer"]],"gear":{"weapon":{"slot":"weapon","family":"wand","tier":2,"name":"Hedge Wand","kind":"magic","from":"Bought from Widow Saffery in Carrbridge","day":10},"armor":{"slot":"armor","family":"cloth","tier":2,"name":"Traveler's Garb","from":"Bought from Widow Saffery in Carrbridge","day":14},"offhand":{"slot":"offhand","family":"tome","tier":1,"name":"Spellbook","from":"Bought in Carrbridge","day":24},"head":{"slot":"head","family":"circlet","tier":1,"name":"Silver Circlet","from":"A gift from the guild on her new calling","day":22},"back":null,"neck":null,"ring1":null,"ring2":null,"pocket":{"slot":"pocket","curio":"warm_egg","name":"Egg That Is Still Warm","from":"on the kobold in Cragtooth Warren","day":28,"history":[{"day":28,"text":"Found on the kobold in Cragtooth Warren, by Katie"},{"day":30,"text":"Lost to Allie on a bet at checkers, at camp in Cragtooth Warren"}],"owners":["h16","h4"]},"belt":null,"boots":null,"gloves":null},"inv":{"ration":3,"potion":2,"torch":6,"bandit_sausage":2,"ore":2,"trinket":3,"goblin_ear":3,"walking_cap":1},"xp":230,"relics":[],"xp_next":583,"stress":1,"stress_why":[["nights in the dark",31],["a dream come true",-27],["camping out",12],["a game by the fire",-9],["a good night underground",-9],["good company",-6]],"fears":["the dark","rats"],"food":"cheap swill","habits":["generous","frugal"],"hobby":"sleeping","hobby_spent":0,"folk":{"carrbridge":{"barkeep":10,"merchant":14},"thornwall":{"barkeep":4},"hollowood":{"barkeep":2},"ironhaven":{"barkeep":2}},"diary":[[4,"worked a shift as a tavern bard (9s)"],[4,"reached level 3 (learned Blink)"],[5,"worked a shift as a dockhand (9s)"],[6,"watched a summer storm cross the plain an hour off, like a slow grey animal"],[7,"lay in the long grass of the King's Road and watched the clouds"],[8,"Allie keeps vigil all night so the crew can sleep, and meets the dawn calm and clear."],[8,"Katie and Allie rank every innkeeper they've met, with reasons"],[8,"reached level 5 (learned Lanternlight; learned Vigil)"],[9,"Allie hangs three tiny flames over camp like lanterns. Katie reads by one until late."],[9,"reached level 6 (learned Arc Lightning)"],[10,"traded up to a Hedge Wand from Widow Saffery for 64s"],[10,"spent part of the day in Carrbridge watching a juggler who drops everything but the knives"],[11,"bought a Star-Stitched Hat from Widow Saffery in Carrbridge for 9s"],[12,"A ghost story from Allie makes Katie check behind the log, twice."],[12,"reached level 7 (learned Mana Surge)"],[13,"Katie takes the last roll by a single pip, and Allie checks the pip. A rivalry begins this evening between Katie and Allie, with the Knucklebone Dice as the witness. Allie lost the bet and now guards the dark, cheerful and annoyed at once."],[13,"reached level 8 (learned Ice Wall)"],[14,"sold 1 fang for 3s"],[14,"traded up to a Traveler's Garb from Widow Saffery for 62s"],[14,"bought the Slate and Chalk Checkers in Carrbridge for 6 silver 4 copper, dear because it was made elsewhere"],[14,"Allie has some Spice-Barge Pilaf at The Honest Toll and sends compliments to Jolly Mott. It has a raisin in every third mouthful, by tradition. (2 silver)",{"meal":"m1"}],[14,"talked with Harry about what the guild clerks actually do all day"],[14,"Katie lets Allie win at dice, badly, and Allie pretends not to notice"],[15,"Allie and Katie walk Thornwall end to end looking for the best bakery, and agree on two."],[16,"Allie stops at a wayside grave to say the words for a stranger. It takes a minute. It matters."],[17,"The Hollowood crier, half-drunk on importance, reads out Allie's name among the notable citizens by mistake. The square cheers. Allie bows."],[18,"told the truth when a small lie would have been easier, and felt better for it"],[19,"sold 1 pelt for 6s"],[20,"Allie carries a flame cupped in her palm along the night road. The wind never touches it. Lanternlight: one of the things Allie learned the long way round."],[21,"Allie finds a kill someone else left: a deer half-eaten under the ferns, the marks of big teeth on the bone. Whatever did it is near."],[21,"Allie reads the Good Dog Tarot for Katie on a folded cloak: the Five of Cups, the Seven of Wands and the Seven of Swords upside down. Allie says it could go either way.",{"reading":"r21"}],[22,"Allie leaves the nest alone, steps wide around it and watches the hen circle back. The woods are a larder, but not that one.",{"road_rec":"r22"}],[22,"reached level 9 (became a Cryomancer)"],[23,"Katie resigns with a bow, a sigh and a promise. The very first game between Allie and Katie is over, and it has set the tone. Stake paid: Katie will take the first watch while everyone else goes to sleep.",{"night":"n21"}],[24,"emptied 1 fish, 1 trinket onto a Carrbridge counter for 12s"],[24,"bought a Spellbook from Widow Saffery in Carrbridge for 13s"],[24,"bought the Driftwood Chess in Carrbridge for 11 silver, dear because it was made elsewhere"],[24,"Allie ties a smart ribbon on Pepper for a stroll round Carrbridge. Pepper much prefers chewing the end of it."],[25,"A game of tag, a trip, a cry, and a bandage. Allie apologises for the knee."],[25,"Allie and Katie spend the afternoon in Ironhaven fixing each other's gear and arguing about knots."],[25,"Allie lights the Ironhaven street lamps for a lamplighter with a bad back. Payment: soup."],[26,"Ration-Bag Hash in Cragtooth Warren, by Katie. Allie goes very quiet, which is how Allie says thank you for her favourite.",{"meal":"m34"}],[27,"in the new dig, on the first floor of Cragtooth Warren: Somebody's crumbs, somebody's blood and somebody's footprints at the new dig, and none of them the crew's. Nothing else is left."],[27,"Katie cooks some Twist-Bread on a Stick in Cragtooth Warren. It has a scorch mark exactly where the cook looked away.",{"meal":"m36"}],[27,"On move 7, Katie hangs the queen and pretends it was a sacrifice. Allie finds the mate on move 52, a queen doing the honours. The very first game between Allie and Katie is over, and it has set the tone. Allie wins and settles in with a warm drink while Katie scrubs the pots.",{"night":"n31"}],[27,"Allie and Katie stay up late swapping stories"],[28,"in the chief's hall, on the first floor of Cragtooth Warren: A kobold in a bucket helmet sits on a stone throne. He stands up. So does everyone else. Allie listens at the crawl and then looks: 2 kobolds and a goblin archer. Everyone knows the job now. A miner's tin under a fallen beam holds a pair of Stout Boots."],[28,"slept well in the chief's hall, for underground"],[28,"Allie sings \"Parsley, Sage and Thyme\" three times, a little better each time. The crew pretend to be asleep by the third. Rufus yawns, loudly, in the second verse.",{"night":"n35","music":true}],[28,"Allie builds Katie an ice chair. It is surprisingly comfortable, briefly."],[28,"reached level 10 (learned Lightning Bolt)"],[29,"in the stolen-goods bin, on the first floor of Cragtooth Warren: A bin the size of a small cart is full of other people's things. At the bottom there is probably something good. Allie finds a hiding place and the half of it that the damp didn't ruin. Somebody left 9 silver here and never came back for it. Allie spots a kobold-sized handle low in the stone."],[29,"found a dry corner of the stolen-goods bin and didn't stir till morning"],[29,"Katie arm-wrestles Allie for the last sausage, loses on purpose, and pretends not to have. (Undefeated at the Table, if anyone's asking.)"],[29,"Frost creeps up the walls around Allie and the monsters go quiet and stay away."],[29,"Move for move, it's the Sire's Trap, as the Sire of a Saltmarrow café laid it, giving up his queen for a mate by three small pieces, and someone at the fire says so. 7 moves. Allie mates Katie with the knight and goes back to supper. Katie loses and so keeps the fire company through the long first hours.",{"night":"n37"}],[30,"in the tribute line, on the bottom floor of Cragtooth Warren: Kobolds trot in single file with a chest on each head. At the sight of strangers every chest is put down. Allie counts heads from the shadows: 3 goblin archers. Now they know what they're walking into. A note in the corner reads 'nothing here, sorry', and it is right."],[30,"made a bed of packs in the tribute line and slept like a child"],[30,"Allie jumps the last piece and sits back, calm as a pond. Katie staked the Egg That Is Still Warm on the game, and Allie has it now.",{"night":"n39"}],[30,"reached level 11 (Frost Shard, honed)"]],"events":[{"id":"e5","day":1,"season":1,"sday":1,"kind":"join","imp":1,"text":"Allie joins the league: a purple-clad Mage with a dog named Pepper, arriving in Saltmarrow with 30 silver and a twig wand.","heroes":["h4"],"parties":[],"loc":"saltmarrow"},{"id":"e18","day":1,"season":1,"sday":1,"kind":"legend","imp":4,"text":"An afternoon with Brother Toad, Keeper of the Long Road, leaves Allie sore all over in Saltmarrow, and noticeably better for it.","heroes":["h4"],"parties":[],"loc":"saltmarrow","wx":"fog"},{"id":"e23","day":1,"season":1,"sday":1,"kind":"levelups","imp":1,"text":"Level-ups: Corrine to 3 (learned Camp Cook; learned Volley); Mark to 3 (learned Blink; learned Arcane Shield); Allie to 2 (learned Mend Wounds).","heroes":["h7","h14","h4"],"parties":[]},{"id":"e56","day":3,"season":1,"sday":3,"kind":"party_formed","imp":4,"text":"Allie and Katie shake on it at The Honest Toll: they are now The Pack of Carrbridge. Honourable, by the look of them.","heroes":["h4","h16"],"parties":["p3"],"loc":"carrbridge"},{"id":"e78","day":4,"season":1,"sday":4,"kind":"levelups","imp":1,"text":"Level-ups: Matt to 6 (learned Studious); Keenan to 5 (learned Studious; learned Blink); Joshua to 5 (learned Arc Lightning; learned Arcane Shield); Cade to 5 (learned Medic; learned Haggler); Allie to 3 (learned Blink); and 1 more.","heroes":["h15","h9","h11","h13","h4"],"parties":[]},{"id":"e105","day":7,"season":1,"sday":7,"kind":"meet","imp":1,"text":"Mark and Allie swap stories on the King's Road while The Black Pack and The Pack of Carrbridge swap rumours.","heroes":["h14","h3","h10","h4","h16"],"parties":["p1","p3"],"loc":"kingsroad"},{"id":"e117","day":8,"season":1,"sday":8,"kind":"fight","imp":3,"text":"First blood for Allie and Katie: The Pack of Carrbridge routs a Bandit Captain, a Wolf and a Bandit Archer on the King's Road and comes away with 6 stolen goods and 1 fang.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f20","foes":["bandit_captain","wolf","bandit_archer"],"where":"in The King's Road","won":true,"close":false},{"id":"e120","day":8,"season":1,"sday":8,"kind":"meet","imp":1,"text":"Andrew and Allie swap stories on the King's Road while The Royal Shadows and The Pack of Carrbridge swap rumours.","heroes":["h9","h13","h11","h2","h4","h16"],"parties":["p2","p3"],"loc":"kingsroad"},{"id":"e121","day":8,"season":1,"sday":8,"kind":"pet","imp":2,"text":"Pepper follows Rufus everywhere today. Allie says it's a phase. Katie says it's love.","heroes":["h16","h4"],"parties":[],"loc":"kingsroad"},{"id":"e124","day":8,"season":1,"sday":8,"kind":"levelups","imp":1,"text":"Level-ups: Matt to 7 (learned Barterer); Harry to 5 (learned Linguist; learned Blink; learned Studious); Allie to 5 (learned Lanternlight; learned Vigil); Jeff to 5 (learned Quick Shot; Field Dressing rank 2); Katie to 5 (learned Cleave; learned Second Wind; learned Angler); and 3 more.","heroes":["h15","h1","h4","h12","h16"],"parties":[]},{"id":"e134","day":9,"season":1,"sday":9,"kind":"fight","imp":2,"text":"The Pack of Carrbridge beats 2 Bandit Captains and a Bandit on the King's Road. Katie's Cleave did the damage (2 times). Loot: 10 stolen goods, 3 rations, 1 gem.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f23","foes":["bandit_captain","bandit","bandit_captain"],"where":"in The King's Road","won":true,"close":false},{"id":"e135","day":9,"season":1,"sday":9,"kind":"talent","imp":2,"text":"Allie hangs three tiny flames over camp like lanterns. Katie reads by one until late.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","skill":"lanternlight"},{"id":"e139","day":9,"season":1,"sday":9,"kind":"pet","imp":2,"text":"Pepper picks Katie out of the whole room at the camp and won't be argued with. Allie sighs and moves seats.","heroes":["h4","h16"],"parties":[],"loc":"kingsroad"},{"id":"e141","day":9,"season":1,"sday":9,"kind":"levelups","imp":1,"text":"Level-ups: Matt to 8 (learned Toll Talker); Allie to 6 (learned Arc Lightning); Katie to 6 (Angler rank 2); Morgan to 2 (learned Recruiter).","heroes":["h15","h4","h16","h18"],"parties":[]},{"id":"e151","day":10,"season":1,"sday":10,"kind":"sale","imp":1,"text":"Allie empties her pack onto a counter in Carrbridge: 1 gem. 39 silver.","heroes":["h4"],"parties":[],"loc":"carrbridge","amount":39},{"id":"e159","day":10,"season":1,"sday":10,"kind":"dream","imp":2,"text":"Late at night Allie counts it up again: to master the craft and reach level 18. Level 6, with 18 still a long climb off.","heroes":["h4"],"parties":[]},{"id":"e185","day":11,"season":1,"sday":11,"kind":"campfire","imp":2,"text":"Katie carves Allie's initials into the campfire log. Allie carves a rude drawing next to them. Friendship.","heroes":["h16","h4"],"parties":["p3"],"loc":"kingsroad","wx":"heat"},{"id":"e191","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"The Pack of Carrbridge sets their sights for the season: to sit beneath the Mother Oak in Hollowood. \"Just sit,\" says Katie. \"Under a tree. With snacks. I've earned it.\"","heroes":["h4","h16"],"parties":["p3"]},{"id":"e202","day":12,"season":1,"sday":12,"kind":"fight","imp":1,"text":"The Pack of Carrbridge beats a Bandit and a Bandit Archer on the King's Road. Loot: 1 bag of stolen goods, 1 ration.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f32","foes":["bandit","bandit_archer"],"where":"in The King's Road","won":true,"close":false},{"id":"e226","day":12,"season":1,"sday":12,"kind":"levelups","imp":1,"text":"Level-ups: Allie to 7 (learned Mana Surge); Katie to 7 (learned Bone Carver); Corrine to 6 (learned Thorn Whip); Griffin to 4 (learned Haggler); Morgan to 4 (learned Tailwind; learned Second Wind).","heroes":["h4","h16","h7","h5","h18"],"parties":[]},{"id":"e231","day":13,"season":1,"sday":13,"kind":"fight","imp":2,"text":"The Pack of Carrbridge outlasts a Bandit Captain, a Bandit and a Wolf on the King's Road. Nobody invited the wolves. They came anyway, drawn by the noise, and made it everyone's problem. Katie's Cleave did the damage (3 times). Loot: 5 stolen goods, 2 rations, 2 fangs & claws.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f37","foes":["bandit_captain","bandit","wolf"],"where":"in The King's Road","won":true,"close":true},{"id":"e241","day":13,"season":1,"sday":13,"kind":"night_game","imp":3,"text":"A rivalry is born at camp on the King's Road: Katie beats Allie at dice, and Allie wants a rematch already.","heroes":["h16","h4"],"parties":[],"loc":"kingsroad","rivalry":"h16|h4"},{"id":"e245","day":13,"season":1,"sday":13,"kind":"levelups","imp":1,"text":"Level-ups: Andrew to 8 (Last Stand rank 2); Allie to 8 (learned Ice Wall); Keenan to 8 (learned Magic Missile); Joshua to 8 (learned Scrying); Cade to 8 (learned Quick Shot); and 4 more.","heroes":["h2","h4","h9","h11","h13"],"parties":[]},{"id":"e255","day":14,"season":1,"sday":14,"kind":"town","imp":3,"text":"Fire at the bakery in Carrbridge! Allie joins the bucket line. They come out smelling of smoke and burnt bread.","heroes":["h4"],"parties":[],"loc":"carrbridge"},{"id":"e277","day":14,"season":1,"sday":14,"kind":"bond","imp":2,"text":"Allie and Katie have become friends, the slow, honest kind that starts with sharing a fire.","heroes":["h4","h16"],"parties":[],"loc":"carrbridge","bond":"friends"},{"id":"e335","day":16,"season":1,"sday":16,"kind":"talent","imp":1,"text":"Allie stops at a wayside grave to say the words for a stranger. It takes a minute. It matters.","heroes":["h4"],"parties":["p3"],"loc":"thornwall","skill":"vigil"},{"id":"e344","day":17,"season":1,"sday":17,"kind":"town_life","imp":2,"text":"The Hollowood crier, half-drunk on importance, reads out Allie's name among the notable citizens by mistake. The square cheers. Allie bows.","heroes":["h4"],"parties":[],"loc":"hollowood","wx":"fog"},{"id":"e357","day":17,"season":1,"sday":17,"kind":"campfire","imp":1,"text":"Two weeks into The Pack of Carrbridge, Allie can tell Katie's boots from everyone else's by the sound.","heroes":["h4","h16"],"parties":["p3"],"loc":"hollowood","wx":"fog"},{"id":"e362","day":17,"season":1,"sday":17,"kind":"goal_done","imp":4,"text":"PILGRIMAGE: The Pack of Carrbridge reaches Hollowood at last and sits beneath the Mother Oak; nobody says much, and everybody walks back lighter. \"It was Katie's idea,\" says Allie, \"and it was a good one.\"","heroes":["h4","h16"],"parties":["p3"],"loc":"hollowood","wx":"fog"},{"id":"e395","day":19,"season":1,"sday":19,"kind":"ambush","imp":2,"text":"The Pack of Carrbridge gets the better of 3 Wolves on the road to Thornwall. The wolf took Katie's Cleave full on and was never the same after. Allie's Frost Shard did the damage (2 times). Loot: 2 pelts, a wolf haunch.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f54","foes":["wolf","wolf","wolf"],"where":"on the road to Thornwall","won":true,"close":false,"shape":"plain","reworded":1},{"id":"e396","day":19,"season":1,"sday":19,"kind":"road","imp":3,"text":"Supper on the road: Marigold sets up the pot, Katie is given the spoon to hold, and the smell makes the miles ahead seem short.","heroes":["h16","h4"],"parties":["p3"],"road":"hollowood~thornwall","traveller":"marigold","road_rec":"r7"},{"id":"e432","day":20,"season":1,"sday":20,"kind":"night","imp":2,"text":"Something sings in the dark on the King's Road. Katie goes to look and comes back with a trinket and a very quiet manner.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e444","day":20,"season":1,"sday":20,"kind":"talent","imp":1,"text":"Allie carries a flame cupped in her palm along the night road. The wind never touches it. Lanternlight: one of the things Allie learned the long way round.","heroes":["h4"],"parties":["p3"],"loc":"kingsroad","skill":"lanternlight"},{"id":"e448","day":20,"season":1,"sday":20,"kind":"pet","imp":1,"text":"Pepper growls at the dark beyond the fire at the King's Road until Allie gets up to look. Nothing there. Pepper is not convinced.","heroes":["h4"],"parties":[],"loc":"kingsroad"},{"id":"e508","day":22,"season":1,"sday":22,"kind":"evolve","imp":4,"text":"Allie the Mage is a Cryomancer now, after a career of frost led by Ice Wall and Frost Shard. Cold hands, colder stare. Her first new trick is Glacial Wall, and the guild has sent a Silver Circlet to go with it.","heroes":["h4"],"parties":[],"cls_from":"mage","cls_to":"cryomancer"},{"id":"e509","day":22,"season":1,"sday":22,"kind":"fight","imp":1,"text":"Two Bandit Archers and a Bandit learn the hard way not to bother the Pack of Carrbridge on the King's Road. Allie's Arc Lightning went off among them; two bandit archers stayed down. Loot: 23 silver each, 2 stolen goods, 2 bandit sausages.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f67","foes":["bandit_archer","bandit_archer","bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"foe","reworded":-27,"wx":"rain"},{"id":"e527","day":22,"season":1,"sday":22,"kind":"song","imp":3,"text":"A fiddler at The Watching Oak plays \"Allie, Allie, Bring the Silver Home\" for the first time, a song about the road Allie's crew finally finished. Somebody at the back asks for it again before it's even over.","heroes":["h4"],"parties":[],"loc":"hollowood","song":"s22_9","wx":"fog"},{"id":"e535","day":22,"season":1,"sday":22,"kind":"pet","imp":1,"text":"Pepper digs a hole at the King's Road, buries Allie's spare sock in it, and stands guard over the spot all evening.","heroes":["h4"],"parties":[],"loc":"kingsroad","wx":"rain"},{"id":"e539","day":22,"season":1,"sday":22,"kind":"levelups","imp":1,"text":"Level-ups: Harry to 11 (learned Barterer); Allie to 9 (became a Cryomancer).","heroes":["h1","h4"],"parties":[]},{"id":"e549","day":23,"season":1,"sday":23,"kind":"fight","imp":1,"text":"On the King's Road, the Pack of Carrbridge squares up to a Bandit and carries the day. Allie wove Glacial Wall over the others and they felt it. Look past the blows: Allie's Ice Wall was the difference. Loot: 9 silver each, 1 bag of stolen goods, 1 ration.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f69","foes":["bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"place","reworded":-27,"wx":"rain"},{"id":"e564","day":23,"season":1,"sday":23,"kind":"night_game","imp":1,"text":"Allie and Katie settle in over checkers at camp on the King's Road, and Allie takes the first one. Katie writes it down, which is a bad sign.","heroes":["h4","h16"],"parties":[],"loc":"kingsroad","wx":"rain","night":"n21"},{"id":"e565","day":23,"season":1,"sday":23,"kind":"bond","imp":4,"text":"Allie and Katie are best friends now. They finish each other's sentences, badly.","heroes":["h4","h16"],"parties":[],"loc":"kingsroad","bond":"best friends","wx":"rain"},{"id":"e608","day":24,"season":1,"sday":24,"kind":"dream","imp":3,"text":"To nobody in particular, Allie raises a cup tonight to the season's dream: master the craft and gain 10 levels. 2 new levels left, close enough to taste.","heroes":["h4"],"parties":[]},{"id":"e613","day":25,"season":1,"sday":25,"kind":"road","imp":3,"text":"On the road, Allie agrees to try the Doctor's famous tonic. It is mostly honey and fear, and does them no harm whatever.","heroes":["h4","h16"],"parties":["p3"],"road":"carrbridge~ironhaven","traveller":"loom","road_rec":"r37"},{"id":"e633","day":25,"season":1,"sday":25,"kind":"pet","imp":1,"text":"Pepper falls asleep in front of the fire at The Gilded Flagon and runs in its dreams. The regulars place bets on what Pepper is chasing.","heroes":["h4"],"parties":[],"loc":"ironhaven"},{"id":"e637","day":25,"season":1,"sday":25,"kind":"bond","imp":3,"text":"Bad blood between The Pack of Carrbridge and The Rose Ledger, and it starts with Allie and Jeff. Three heroes now hold grudges.","heroes":["h4","h12","h16"],"parties":["p3","p6"],"loc":"carrbridge","bond":"rivals"},{"id":"e638","day":25,"season":1,"sday":25,"kind":"meet","imp":1,"text":"Jeff knows Katie's walk from a long way off on the road between Carrbridge and Ironhaven, and The Pack of Carrbridge and The Rose Ledger stop for a proper talk.","heroes":["h4","h16","h12","h1"],"parties":["p3","p6"],"loc":"carrbridge"},{"id":"e648","day":26,"season":1,"sday":26,"kind":"ambush","imp":2,"text":"Allie takes the worst of it as the Pack of Carrbridge dispatches a Bandit Archer on the road to Cragtooth Warren. The fight turned on Allie's Frost Shard. Katie's Berserk did the work nobody saw. Loot: 8 silver each, 1 bag of stolen goods.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad","fight":"f73","foes":["bandit_archer"],"where":"on the road to Cragtooth Warren","won":true,"close":false,"shape":"hero","reworded":-31},{"id":"e649","day":26,"season":1,"sday":26,"kind":"road","imp":2,"text":"Allie beats out a stack fire beside the road to Cragtooth Warren with a wet coat and a lot of language. The farm is saved, and the farmer loads her down with bread.","heroes":["h4","h16"],"parties":["p3"],"road":"cragtooth_warren~ironhaven","road_rec":"r45"},{"id":"e667","day":26,"season":1,"sday":26,"kind":"meet","imp":1,"text":"Andrew produces a bad map outside Cragtooth Warren, and the meeting with The Pack of Carrbridge goes better than anyone planned.","heroes":["h9","h13","h11","h2","h4","h16"],"parties":["p2","p3"],"loc":"cragtooth_warren"},{"id":"e673","day":26,"season":1,"sday":26,"kind":"omen_true","imp":2,"text":"The Seven of Wands, said Allie to Katie five days ago. Katie has been in 3 fights since and nothing got through.","heroes":["h16","h4"],"parties":[],"loc":"cragtooth_warren","reading":"r21"},{"id":"e676","day":26,"season":1,"sday":26,"kind":"campfire","imp":2,"text":"Allie and Katie share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren"},{"id":"e701","day":27,"season":1,"sday":27,"kind":"delve","imp":1,"text":"Into Cragtooth Warren goes The Pack of Carrbridge, with the place partly explored (59%).","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren","wx":"heat"},{"id":"e712","day":27,"season":1,"sday":27,"kind":"night_game","imp":1,"text":"First game of chess between Allie and Katie, at camp in Cragtooth Warren: Allie by a whisker, and both are already keeping score.","heroes":["h4","h16"],"parties":[],"loc":"cragtooth_warren","wx":"heat","night":"n31"},{"id":"e728","day":28,"season":1,"sday":28,"kind":"keystone","imp":2,"text":"Frost races out from Allie's feet, and every foe on the field is bitten by it and slowed to a shiver. Endless Winter: a freezing blast that hurts every enemy and leaves them sluggish.","heroes":["h4"],"parties":[],"keystone":"endless_winter","ks":"Endless Winter","level":10},{"id":"e731","day":28,"season":1,"sday":28,"kind":"fight","imp":1,"text":"The Pack of Carrbridge sees off 2 Kobolds and a Goblin Archer in the chief's hall on the first floor of Cragtooth Warren. Two kobolds went down together, and they have Katie's Cleave to thank. It was Allie's Ice Wall that tilted it, quietly. Loot: 7 silver each, 1 ore, 2 trinkets. Allie's hands shake the whole fight. The dark, of all things. Allie fights anyway.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren","fight":"f76","foes":["kobold","kobold","goblin_archer"],"where":"in the chief's hall on the first floor of Cragtooth Warren","won":true,"close":false,"shape":"plain"},{"id":"e747","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Allie builds Katie an ice chair. It is surprisingly comfortable, briefly.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren","skill":"endless_winter"},{"id":"e751","day":28,"season":1,"sday":28,"kind":"levelups","imp":1,"text":"Level-ups: Allie to 10 (learned Lightning Bolt); Katie to 10 (learned Shield Wall); Morgan to 9 (with the season goal; Sentry, mastered; learned Field Dressing; became a Beastmaster); Olivia to 8 (Banishing Rite, honed).","heroes":["h4","h16","h18","h10"],"parties":[]},{"id":"e755","day":29,"season":1,"sday":29,"kind":"edict","imp":3,"text":"The Elder of Hollowood, Osric the Thrifty, bans the song \"Allie, Allie, Bring the Silver Home\" within the walls. The bard who wrote it asks for the ban in writing, to frame.","heroes":["h4"],"parties":[],"loc":"hollowood"},{"id":"e761","day":29,"season":1,"sday":29,"kind":"trap","imp":2,"text":"Allie springs a rotten beam in a kobold-sized stair that has to be taken sideways on the first floor of Cragtooth Warren (sprained ankle) (Katie hurt too).","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren"},{"id":"e762","day":29,"season":1,"sday":29,"kind":"fight","imp":1,"text":"Two Goblin Archers and a Kobold pick a fight with the Pack of Carrbridge in the new dig on the first floor of Cragtooth Warren and come off worst. Allie cast Endless Winter into the middle of them, and two goblin archers didn't get up. Loot: 9 silver each, 3 goblin ears, 2 walking-caps.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren","fight":"f77","foes":["goblin_archer","goblin_archer","kobold"],"where":"in the new dig on the first floor of Cragtooth Warren","won":true,"close":false,"shape":"foe","reworded":-31},{"id":"e764","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Katie arm-wrestles Allie for the last sausage, loses on purpose, and pretends not to have. (Undefeated at the Table, if anyone's asking.)","heroes":["h16","h4"],"parties":["p3"],"loc":"cragtooth_warren","skill":"undefeated_at_the_table"},{"id":"e765","day":29,"season":1,"sday":29,"kind":"night","imp":2,"text":"Allie trades a ration with a stranger who wasn't there at dusk and isn't there at dawn. The trinket stays.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren"},{"id":"e777","day":29,"season":1,"sday":29,"kind":"talent","imp":1,"text":"Frost creeps up the walls around Allie and the monsters go quiet and stay away.","heroes":["h4"],"parties":["p3"],"loc":"cragtooth_warren","skill":"endless_winter"},{"id":"e779","day":29,"season":1,"sday":29,"kind":"night_game","imp":2,"text":"Move for move, it's the Sire's Trap, as the Sire of a Saltmarrow café laid it, giving up his queen for a mate by three small pieces, and someone at the fire says so. 7 moves. Allie mates Katie with the knight and goes back to supper. Katie loses and so keeps the fire company through the long first hours.","heroes":["h4","h16"],"parties":[],"loc":"cragtooth_warren","night":"n37"},{"id":"e789","day":30,"season":1,"sday":30,"kind":"fight","imp":1,"text":"The Pack of Carrbridge, in fine spirits lately, cuts down 3 Goblin Archers in the tribute line on the bottom floor of Cragtooth Warren. Three of them fell to Katie's Cleave. Loot: 7 silver each, 3 goblin ears, 2 walking-caps.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren","fight":"f81","foes":["goblin_archer","goblin_archer","goblin_archer"],"where":"in the tribute line on the bottom floor of Cragtooth Warren","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e802","day":30,"season":1,"sday":30,"kind":"sniped","imp":3,"text":"Deep in Cragtooth Warren, The Pack of Carrbridge hears the roaring below go quiet: The Royal Shadows reached The Mimic King first. The Pack stays and works the floors that are left.","heroes":["h4","h16","h9","h13","h11","h2"],"parties":["p3","p2"],"loc":"cragtooth_warren","snipers":["h9","h13","h11","h2"],"where":"inside","boss":"The Mimic King","in_fight":"f82"},{"id":"e816","day":30,"season":1,"sday":30,"kind":"campfire","imp":1,"text":"Allie and Katie share the last pickled onion by cutting it exactly in half, with witnesses.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren"},{"id":"e817","day":30,"season":1,"sday":30,"kind":"ambition","imp":5,"text":"Allie has gained 10 levels this season, a true master of the craft, and it goes in the Annals in ink. Next on the list: to set foot in six of the realm's towns.","heroes":["h4"],"parties":[],"ambition":"master"},{"id":"e819","day":30,"season":1,"sday":30,"kind":"levelups","imp":1,"text":"Level-ups: Keenan to 14 (with the season goal; Studious, honed; learned Packmule); Andrew to 13 (with the season goal; Berserk, honed; learned Bloodlust); Joshua to 13 (with the season goal; learned Everburning Light; Arcane Shield, honed); Cade to 13 (with the season goal; Headshot, honed; learned Snare); Allie to 11 (Frost Shard, honed); and 2 more.","heroes":["h9","h2","h11","h13","h4"],"parties":[]},{"id":"e824","day":30,"season":1,"sday":30,"kind":"delve_done","imp":3,"text":"After 4 days The Pack of Carrbridge climbs the last ladder and sits down at the top of it. They went as deep as the place goes, took 6 rooms off the map, mapped 43%, turned up the chief's hall and split 55 silver. No boss, but the place paid. Cragtooth Warren is 89% explored.","heroes":["h4","h16"],"parties":["p3"],"loc":"cragtooth_warren","days":4,"bottom":true,"rooms":["the chief's hall"],"gold":55},{"id":"e825","day":30,"season":1,"sday":30,"kind":"healed","imp":1,"text":"The last of the sprained ankle fades, and Allie celebrates with a long walk to nowhere.","heroes":["h4"],"parties":[]},{"id":"e1000000001","day":30,"season":1,"sday":30,"kind":"closing_games","imp":2,"text":"THE CLOSING GAMES (Arm-Wrestling): Harry puts Katie down in the final for the Iron Knuckle, then has to sit very still for a bit. Eight heroes entered: Mark, Katie, Harry, Jeff, Joshua, Griffin, Allie and Morgan. 12th in the table, first at the Games. Harry will take it.","heroes":["h1","h14","h16","h12","h11","h5","h4","h18"],"parties":[]}],"rels":[{"hero":"h16","score":100,"bond":"best friends","mentor":null,"mate":true},{"hero":"h12","score":-61,"bond":"rivals","mentor":null,"mate":false},{"hero":"h9","score":34,"bond":null,"mentor":null,"mate":false},{"hero":"h11","score":31,"bond":null,"mentor":null,"mate":false},{"hero":"h13","score":30,"bond":null,"mentor":null,"mate":false},{"hero":"h2","score":26,"bond":null,"mentor":null,"mate":false},{"hero":"h1","score":12,"bond":null,"mentor":null,"mate":false},{"hero":"h5","score":8,"bond":null,"mentor":null,"mate":false},{"hero":"h3","score":6,"bond":null,"mentor":null,"mate":false}],"debts":[],"season":{"kills":10,"bosses":0,"gold_earned":300,"dmg":843,"healed":78,"fights":11,"wins":11,"fled":0,"downed":0,"levels":10,"loot_sold":60,"days_worked":2,"delves":1,"floors":2,"pvp_wins":0,"pvp_losses":0,"robbed":0,"robberies":0,"injuries":1,"contracts":0,"travel_days":16,"renown":45,"corpses_sold":0,"best_sale":39,"deaths_witnessed":0,"gambled":0,"bounties":29,"best_day":35,"taken":36,"steady":11.88,"band_kills":11.5,"band_delves":0.5,"band_floors":1.0},"season_closed":true,"career":{"kills":10,"bosses":0,"gold_earned":300,"dmg":843,"healed":78,"fights":11,"wins":11,"fled":0,"downed":0,"levels":10,"loot_sold":60,"days_worked":2,"delves":1,"floors":2,"pvp_wins":0,"pvp_losses":0,"robbed":0,"robberies":0,"injuries":1,"contracts":0,"travel_days":16,"renown":45,"corpses_sold":0,"best_sale":39,"deaths_witnessed":0,"gambled":0,"bounties":29,"best_day":35,"taken":36,"steady":11.88,"band_kills":11.5,"band_delves":0.5,"band_floors":1.0},"past":[{"season":1,"renown":170,"level":11,"cls":"cryomancer","stats":{"kills":10,"bosses":0,"gold_earned":300,"dmg":843,"healed":78,"fights":11,"wins":11,"fled":0,"downed":0,"levels":10,"loot_sold":60,"days_worked":2,"delves":1,"floors":2,"pvp_wins":0,"pvp_losses":0,"robbed":0,"robberies":0,"injuries":1,"contracts":0,"travel_days":16,"renown":45,"corpses_sold":0,"best_sale":39,"deaths_witnessed":0,"gambled":0,"bounties":29,"best_day":35,"taken":36,"steady":11.88,"band_kills":11.5,"band_delves":0.5,"band_floors":1.0}}],"profile":{"maxhp":148,"pow":53.8,"arm":3,"acc":87,"eva":26,"crit":9,"spd":11,"resolve":26,"thorns":0,"vs_big":0,"vs":{},"onhit":[],"lifesteal":0.0,"mind_stat":20,"heart_stat":8,"might":8},"town_rep":{"carrbridge":18,"thornwall":4,"hollowood":3,"ironhaven":3},"regular":{"carrbridge":5,"thornwall":2,"hollowood":1,"ironhaven":1},"jobs":{"bard":1,"dockhand":1},"remains_of":[],"death_cause":null,"death_place":null,"buried":null,"memorial_at":null,"body":null,"quiz":["Allie","Allie",2,0,2,6,0,6,1,0,2,0,0,5,3,5,1,4,1,0,3],"ambition":"to set foot in six of the realm's towns","ambitions_done":["to master the craft and gain 10 levels this season"],"visited":["saltmarrow","carrbridge","thornwall","hollowood","ironhaven"],"tonight":{"setting":"camp","room":null,"biome":"hills","road":false,"floor":null,"theme":null,"host":null,"others":[],"gate":"cragtooth_warren","place":"Camped outside Cragtooth Warren","cast":[{"id":"h4","lines":["I did it. The thing I've wanted since before I left home: to set foot in six of the realm's towns. I'm proud of us.","Someone else killed the boss we were after. We kept working the place anyway. We'll see.","There's enough stew for seconds.","It's a good night to be alive.","Someday I hope to set foot in six of the realm's towns.","Nobody mention the dark tonight.","Pepper has claimed the warm spot.","I miss sleeping.","Katie has my back."],"pet":["Woof.","*thumps tail*","*snores*","*sniffs the air*"]},{"id":"h16","lines":["Someone else killed the boss we were after. We kept working the place anyway. We'll see.","We spent 4 days mapping Cragtooth Warren. Found the chief's hall, which nobody had opened in years. We did right today.","There's enough stew for seconds.","It's a good night to be alive.","Someday I hope to set foot in six of the realm's towns.","My deep cut aches tonight.","Nobody mention deep water tonight.","Rufus keeps eyeing my supper.","I miss flea markets.","Allie has my back."],"pet":["Woof.","*thumps tail*","*snores*","*sniffs the air*"]}],"talk":[[{"id":"h4","text":"That Goblin Archer won't bother anyone again."},{"id":"h16","text":"Couldn't have done it alone."}]],"mounts":[],"wagon":null}};